function dqNormTitle(title) {
  return String(title || "").trim().toLowerCase().replace(/\s+/g, " ");
}
function dqNormLink(link) {
  return String(link || "").trim().toLowerCase().replace(/\/+$/, "");
}
function dqIsDup(existing, candidate) {
  const et_ = dqNormTitle(existing.title);
  const ct = dqNormTitle(candidate.title);
  if (et_ && ct && et_ === ct) return true;
  const el = dqNormLink(existing.link);
  const cl = dqNormLink(candidate.link);
  if (el && cl && el === cl) return true;
  return false;
}
const DQ_DIFFICULTIES = ["Easy", "Medium", "Hard"];
function dqNormalizeQ(raw, genId) {
  const difficulty = DQ_DIFFICULTIES.includes(raw.difficulty) ? raw.difficulty : "Medium";
  return {
    id: raw.id || genId(),
    title: String(raw.title || "").trim(),
    topic: String(raw.topic || "Arrays").trim() || "Arrays",
    difficulty,
    platform: String(raw.platform || "Custom").trim() || "Custom",
    link: String(raw.link || "").trim(),
    solved: !!raw.solved,
    revision: !!raw.revision,
    notes: raw.notes || "",
    status: raw.solved ? "solved" : "pending",
    dateSolved: raw.solved ? raw.dateSolved || null : null,
    companyTags: Array.isArray(raw.companyTags)
      ? raw.companyTags.map((t) => String(t).trim()).filter(Boolean)
      : String(raw.companyTags || "").split(",").map((t) => t.trim()).filter(Boolean),
    pattern: String(raw.pattern || "").trim(),
    attempts: Number.isFinite(Number(raw.attempts)) ? Math.max(0, Math.floor(Number(raw.attempts))) : 0,
    timeTakenMin:
      raw.timeTakenMin != null && raw.timeTakenMin !== "" && !isNaN(Number(raw.timeTakenMin))
        ? Math.max(0, Number(raw.timeTakenMin))
        : null,
    confidence:
      raw.confidence != null && raw.confidence !== "" && !isNaN(Number(raw.confidence))
        ? Math.min(5, Math.max(1, Math.round(Number(raw.confidence))))
        : null,
    solutionCode: raw.solutionCode || "",
    custom: raw.custom !== undefined ? !!raw.custom : true,
    pinned: !!raw.pinned,
    editorialLink: String(raw.editorialLink || "").trim(),
    videoLink: String(raw.videoLink || "").trim(),
    relatedIds: Array.isArray(raw.relatedIds)
      ? raw.relatedIds.map((x) => String(x).trim()).filter(Boolean)
      : String(raw.relatedIds || "").split(",").map((x) => x.trim()).filter(Boolean),
    addedAt: raw.addedAt || Date.now(),
  };
}
function dqDedupe(existingList, candidates, genId) {
  const toAdd = [];
  const duplicates = [];
  const seen = existingList.slice();
  for (const raw of candidates) {
    const candidate = dqNormalizeQ(raw, genId);
    if (!candidate.title) continue;
    const dupe = seen.some((e) => dqIsDup(e, candidate));
    if (dupe) duplicates.push(candidate);
    else {
      toAdd.push(candidate);
      seen.push(candidate);
    }
  }
  return { toAdd, duplicates };
}
function dqParseBulkText(text) {
  const lines = String(text || "").split(/\r?\n/);
  const rows = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const parts = trimmed.split("|").map((p) => p.trim());
    const [title, topic, difficulty, platform, link] = parts;
    if (!title) continue;
    rows.push({ title, topic, difficulty, platform, link });
  }
  return rows;
}
function dqParseCSV(csvText) {
  const text = String(csvText || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  let i = 0;
  const pushField = () => { row.push(field); field = ""; };
  const pushRow = () => { rows.push(row); row = []; };
  while (i < text.length) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      field += c; i++; continue;
    } else {
      if (c === '"') { inQuotes = true; i++; continue; }
      if (c === ',') { pushField(); i++; continue; }
      if (c === '\n') { pushField(); pushRow(); i++; continue; }
      field += c; i++; continue;
    }
  }
  if (field.length > 0 || row.length > 0) { pushField(); pushRow(); }
  while (rows.length && rows[rows.length - 1].every((v) => v === "")) rows.pop();
  if (rows.length === 0) return [];
  const header = rows[0].map((h) => h.trim());
  const out = [];
  for (let r = 1; r < rows.length; r++) {
    const cols = rows[r];
    if (cols.every((v) => v === "")) continue;
    const obj = {};
    header.forEach((h, idx) => { obj[h] = cols[idx] !== undefined ? cols[idx] : ""; });
    out.push(obj);
  }
  return out;
}
